#!/bin/sh
# The workloads for the property obligations (proofs/README.md, "Obligations for the harness").
#
# One workflow with the inputs that vary each *keyed* input kind on its own, and a second that is
# identical but for one extra step before the subject, so the subject's position in the job differs
# while everything else about it does not.
#
#   gen-workflows.sh <outdir>
set -eu
out=${1:?outdir}
mkdir -p "$out"

emit() { # $1 = name, $2 = "yes" to put a filler step before the subject
	name=$1
	filler=$2
	cat <<EOF
# Generated by properties/gen-workflows.sh — do not edit by hand.
name: $name
on:
  workflow_dispatch:
    inputs:
      text:
        description: The subject step's script text
        default: base
      ref:
        description: The commit the workspace is checked out at
        default: 3a33ba578e0dd93444e0ff386cc26e665d92e31e
      envval:
        description: A non-volatile variable the subject step can see
        default: base
      volatile:
        description: yes = the subject step names a run-specific value, so it must always run
        default: "no"
jobs:
  subject:
    runs-on: [self-hosted, zig]
    env:
      PROP_ENV: \${{ inputs.envval }}
    steps:
      - uses: actions/checkout@v4
        with:
          repository: go-chi/chi
          ref: \${{ inputs.ref }}
EOF
	if [ "$filler" = yes ]; then
		cat <<'EOF'
      - name: filler
        run: ": one more step before the subject, so its position differs"
EOF
	fi
	cat <<'EOF'
      - name: subject plain
        if: inputs.volatile == 'no'
        run: |
          : "subject ${{ inputs.text }}"
          wc -c < README.md
          echo "$PROP_ENV"
      - name: subject volatile
        if: inputs.volatile == 'yes'
        run: |
          : "subject ${{ inputs.text }}"
          wc -c < README.md
          echo "$PROP_ENV"
          echo "run $GITHUB_RUN_ID"
      - name: after
        run: ": after the subject"
EOF
}

emit property no > "$out/property.yml"
emit property-shifted yes > "$out/property-shifted.yml"
echo "wrote $out/property.yml and $out/property-shifted.yml" >&2

# P1 and $GITHUB_ENV in one workload: a step that exports a variable, a step whose output depends on
# it and on the workspace, and a per-workflow step-cache opt-out, so the same job can be run with the
# cache off and with it on and the two compared.
cat > "$out/property-replay.yml" <<'EOF'
# Generated by properties/gen-workflows.sh — do not edit by hand.
name: property-replay
on:
  workflow_dispatch:
    inputs:
      step_cache:
        description: "false turns the step cache off for this job (ZIG_RUNNER_STEP_CACHE)"
        default: "true"
jobs:
  replay:
    runs-on: [self-hosted, zig]
    env:
      ZIG_RUNNER_STEP_CACHE: ${{ inputs.step_cache }}
    steps:
      - uses: actions/checkout@v4
        with:
          repository: go-chi/chi
          ref: 3a33ba578e0dd93444e0ff386cc26e665d92e31e
      - name: export
        run: echo "EXPORTED=from-the-export-step" >> "$GITHUB_ENV"
      - name: observe
        run: |
          echo "observed exported=$EXPORTED"
          echo "observed readme=$(wc -c < README.md)"
          echo "observed entries=$(ls -1 | wc -l)"
      - name: after
        run: ": after the observer"
EOF

# Early cutoff: a marked step (it names a run-specific value, so it always runs) whose output is
# either the same bytes every run or new bytes every run, and steps after it that can only be
# replayed when it left the same bytes.
cat > "$out/property-cutoff.yml" <<'EOF'
# Generated by properties/gen-workflows.sh — do not edit by hand.
name: property-cutoff
on:
  workflow_dispatch:
    inputs:
      stable:
        description: "yes = the marked step leaves the same bytes every run; no = new bytes"
        default: "yes"
jobs:
  cutoff:
    runs-on: [self-hosted, zig]
    steps:
      - uses: actions/checkout@v4
        with:
          repository: go-chi/chi
          ref: 3a33ba578e0dd93444e0ff386cc26e665d92e31e
      - name: marked
        run: |
          : "always-run, because it names $GITHUB_RUN_ID"
          if [ "${{ inputs.stable }}" = yes ]; then
            echo fixed > out.txt
          else
            echo "$GITHUB_RUN_ID" > out.txt
          fi
      - name: reader
        run: |
          echo "read $(cat out.txt | wc -c) bytes"
      - name: after
        run: ": after the reader"
EOF
echo "wrote $out/property-replay.yml and $out/property-cutoff.yml" >&2
